# SPDX-License-Identifier: MIT
# Three ways of doing something every 10 ms, and what each one really gives:
#   sleep:  a Python thread that sleeps 10 ms (Linux decides when it wakes up);
#   timer:  machine.Timer: on a board with a Cortex-M4 the M4 counts the expiries and Linux runs
#           the callbacks; on a board without one, a thread of MicroPython on Linux's clock does both;
#   count:  how many expiries were counted, against the time gone by.
# Load: busy Linux processes, one for each core, to see who keeps the time when Linux is busy.
# In the LVGL MPY Studio simulator a stand-in makes up intervals of the same kind.

import time

try:
    import _thread

    import linuxproc
    import machine

    HARDWARE = hasattr(machine, "Timer") and hasattr(machine.Timer, "ONE_SHOT")
except ImportError:
    HARDWARE = False

try:
    import mpy_m4

    MCU = mpy_m4.available()
except ImportError:
    MCU = True  # the simulator tells the Cortex-M4's story


def cores():
    if not HARDWARE:
        return 2  # the simulator's board
    try:
        with open("/proc/cpuinfo") as f:
            return max(1, sum(1 for line in f if line.startswith("processor")))
    except OSError:
        return 2

PERIOD_MS = 10
KEEP = 1000  # intervals kept for each way


class Board:
    def __init__(self):
        self.sleep = []
        self.timer = []
        self.calls = 0
        self.missed = 0
        self._last = None
        self._started = time.ticks_us()
        self._timer = None
        self._load = []

    def start(self):
        self._timer = machine.Timer(0, period=PERIOD_MS, callback=self._expired)
        _thread.start_new_thread(self._sleeper, ())

    def _sleeper(self):
        before = time.ticks_us()
        while True:
            time.sleep_ms(PERIOD_MS)
            now = time.ticks_us()
            self.sleep.append(time.ticks_diff(now, before))
            if len(self.sleep) > KEEP:
                self.sleep.pop(0)
            before = now

    def _expired(self, timer):
        now = time.ticks_us()
        self.calls += 1
        self.missed = timer.missed
        if self._last is not None:
            self.timer.append(time.ticks_diff(now, self._last))
            if len(self.timer) > KEEP:
                self.timer.pop(0)
        self._last = now

    def poll(self):
        pass

    def counted(self):
        # Expiries counted since reset (by the M4, or by the timer thread), and those 10 ms should give.
        expected = time.ticks_diff(time.ticks_us(), self._started) // (PERIOD_MS * 1000)
        return self.calls + self.missed, expected

    def reset(self):
        self.sleep = []
        self.timer = []
        self._timer.init(period=PERIOD_MS, callback=self._expired)  # starts counting again
        self._timer.missed = 0
        self.calls = self.missed = 0
        self._last = None
        self._started = time.ticks_us()

    def load(self, on):
        if on and not self._load:
            for _ in range(cores()):
                self._load.append(linuxproc.Process(["sh", "-c", "while :; do :; done"]))
        elif not on:
            for process in self._load:
                process.kill()
                process.close()
            self._load = []


class Simulated:
    # Linux wakes up a little late, sometimes much later under load; the M4 counts exactly.

    def __init__(self):
        self.sleep = []
        self.timer = []
        self.calls = 0
        self.missed = 0
        self._loaded = False
        self._seed = 1
        self._started = time.ticks_ms()
        self._done = 0

    def _random(self):
        self._seed = (self._seed * 1103515245 + 12345) & 0x7FFFFFFF
        return self._seed / 0x7FFFFFFF

    def start(self):
        pass

    def poll(self):
        due = time.ticks_diff(time.ticks_ms(), self._started) // PERIOD_MS
        while self._done < due:
            self._done += 1
            spread = 1500 if self._loaded else 150
            late = int((self._random() + self._random() - 1) * spread)
            if self._loaded and self._random() < 0.05:
                late += int(self._random() * 3000)
            self.sleep.append(10080 + abs(late))
            self.timer.append(10000 + late)
            self.calls += 1
            for kept in (self.sleep, self.timer):
                if len(kept) > KEEP:
                    kept.pop(0)

    def counted(self):
        due = time.ticks_diff(time.ticks_ms(), self._started) // PERIOD_MS
        return self.calls, due

    def reset(self):
        self.sleep = []
        self.timer = []
        self.calls = 0
        self._started = time.ticks_ms()
        self._done = 0

    def load(self, on):
        self._loaded = on


clock = Board() if HARDWARE else Simulated()
